CREATE TRIGGER
  Fix_TBI_InTrn
  BEFORE INSERT
  ON Fix_InTrn
  FOR EACH ROW
BEGIN
  SET NEW.CQnt = NEW.Qnt;
  If IFNULL(NEW.CQnt,0)<0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No Qnt. For The Item '||NEW.Fixd_Id;
  END If;
  If IFNULL(NEW.CQnt,0)=0 AND IFNULL(NEW.CAmt,0)<>0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Fixd '||NEW.Fixd_Id||' Has Amount Without Quantity';
  END If;
END$$
