CREATE TRIGGER
  Fix_TBI_OuTrn
  BEFORE INSERT
  ON Fix_OuTrn
  FOR EACH ROW
DECLARE
  nPrice    DECIMAL(38,10) := 0;
BEGIN
  SELECT Price
    INTO nPrice
    FROM Fix_InTrn
    WHERE Id=NEW.Trn_Id;
  SET NEW.UCst = IFNULL(nPrice,0);
  SET NEW.Cst = IFNULL(NEW.UCst,0) * IFNULL(NEW.Qnt,0);
  UPDATE Fix_InTrn SET
         CQnt=IFNULL(CQnt,0)-IFNULL(NEW.Qnt,0),
         CAmt=IFNULL(CAmt,0)-IFNULL(NEW.Cst,0)
   WHERE Id=NEW.Trn_Id;
EXCEPTION
  When No_Data_Found THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Undefined Transaction '||NEW.Trn_Id;
END$$
DELIMITER ;

